ON CONFLICT (sa2_code_2021,reference_year) DO UPDATE SET
  census_total_population=EXCLUDED.census_total_population,
  age_65_plus_count=EXCLUDED.age_65_plus_count,
  age_65_plus_percent=EXCLUDED.age_65_plus_percent,
  age_75_plus_count=EXCLUDED.age_75_plus_count,
  age_75_plus_percent=EXCLUDED.age_75_plus_percent,
  under_five_count=EXCLUDED.under_five_count,
  under_five_percent=EXCLUDED.under_five_percent,
